interface Product {
  id: number;
  name: string;
  price: number;
  stock: number;
  tags?: string[];
}

const products: Product[] = [
  { id: 1, name: 'Pen', price: 10, stock: 100, tags: ['stationery'] },
  { id: 2, name: 'Notebook', price: '60', stock: 40 },
  { id: 3, name: 'Bag', price: 900, stok: 5 },
];

function findProduct(id: number): Product {
  return products.find((p) => p.id === id);
}

function tagList(p: Product): string {
  return p.tags.join(', ');
}

function withGst(p: Product): Product {
  return { ...p, price: p.price + (p.price * 18) / 100 };
}

console.log(findProduct(1).name, tagList(findProduct(1)));

const raw: any = JSON.parse('{"id": 4, "name": "Lamp", "price": "1200", "stock": 3}');
const lamp = raw as Product;
console.log('Lamp with GST:', withGst(lamp).price); // expect 1416
